#include <cmath>
#include <algorithm>
extern "C" void raster(const double *p,int N,double *out,int W,int H,double ex,double ey) {
  for(int i=0;i<N;i++) {
    double x=p[3*i]-350,y=p[3*i+1]-498,h=std::max(0.,p[3*i+2]/.22185986964255727-1.802952461)/2;
    double ax=x-h*ex,ay=y-h*ey,bx=x+h*ex,by=y+h*ey;
    int x0=std::max(0,(int)std::floor(std::min(ax,bx)-1.5)),x1=std::min(W-1,(int)std::ceil(std::max(ax,bx)+1.5));
    int y0=std::max(0,(int)std::floor(std::min(ay,by)-1.5)),y1=std::min(H-1,(int)std::ceil(std::max(ay,by)+1.5));
    double dx=bx-ax,dy=by-ay,L=dx*dx+dy*dy;
    for(int v=y0;v<=y1;v++)for(int u=x0;u<=x1;u++) {
      double t=L>1e-14?std::min(1.,std::max(0.,((u-ax)*dx+(v-ay)*dy)/L)):0;
      double d=std::hypot(u-ax-t*dx,v-ay-t*dy);
      double a=std::min(1.,std::max(0.,1.4014762305-d));
      out[v*W+u]=std::max(out[v*W+u],a);
    }
  }
}
